  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C73"],
      "claim": "Zalcitabine absolute oral bioavailability was 86–100% at 5 mg in adults without hepatic or renal dysfunction, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Lamivudine oral solution absolute bioavailability was 87% in fasted patients, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C69"],
      "claim": "Paliperidone ER absolute bioavailability was 28% in healthy volunteers, above the 20% threshold despite being the lowest high-F evidence.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All interpretable transferred evidence supports oral bioavailability above 20%, with most values ranging from 28% to 100%; only altered fed-state didanosine records fell below threshold and were discounted.",
  "evidence_gaps": [
    "Molecule 3 records conflate didanosine and emtricitabine; this provenance conflict prevents using that molecule as evidence.",
    "Molecule 5 fed-state F values (0.17–0.19) are below threshold but were discounted as altered-condition records; food-effect uncertainty remains."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

